  cleanup = await useTemporaryDatabase();
  north = await createTenant("north-k");
  acme = await createTenant("acme-k");
});
afterAll(() => { vi.useRealTimers(); cleanup(); });

describe("keyset", () => {
  it("issues same stamp", async () => {
    for (const t of [north, acme]) {
      for (let i = 0; i < 13; i++) {
        const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
        await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: `i${i}` }), t.userIds.owner, n);
      }
    }
    const all = await issueRepo.listIssues({ orgId: north.org.id, projectId: north.project.id, limit: 100 } as never);
    expect(all.total).toBe(13);
    for (const size of [1, 2, 3, 5, 13, 20]) {
      const seen: string[] = [];
      let cursor: string | null = null;
      do {
        const p = await issueRepo.listIssues({ orgId: north.org.id, projectId: north.project.id, limit: size, cursor } as never);
        seen.push(...p.items.map((x) => x.id));
        cursor = p.nextCursor;
      } while (cursor);
      expect(seen).toEqual(all.items.map((x) => x.id));
    }
  });
  it("notifications same stamp", async () => {
    await notificationRepo.insertNotifications(north.org.id, Array.from({ length: 7 }, (_, i) => ({
      orgId: north.org.id, recipientId: north.userIds.owner, kind: "issue_assigned", title: `n${i}`, body: "", href: "/", actorId: null, channels: ["in_app"],
    })) as never);
    const all = await notificationRepo.listNotifications({ orgId: north.org.id, recipientId: north.userIds.owner, limit: 100 } as never);
    expect(all.items.length).toBe(7);
    const seen: string[] = [];
    let cursor: string | null = null;
    do {
      const p = await notificationRepo.listNotifications({ orgId: north.org.id, recipientId: north.userIds.owner, limit: 2, cursor } as never);
      seen.push(...p.items.map((x) => x.id));
      cursor = p.nextCursor;
    } while (cursor);
    expect(seen).toEqual(all.items.map((x) => x.id));
  });
});
